options.customCss:
/* =========================================================================
   SCHEMESETU — Government Eligibility Assessment Form
   Custom CSS for n8n Form Trigger node ("Custom Form Styling" field)

   HOW TO USE
   1. Open your n8n Form Trigger node
   2. Scroll to "Custom CSS" (Options)
   3. Paste this entire file in
   4. n8n's form reads the CSS custom properties below directly, so the
      :root block alone will re-skin the whole form.
   5. The rules under "STRUCTURAL ENHANCEMENTS" style native input types
      (radio/checkbox) and add the tricolour + emblem — these use generic
      selectors so they render correctly even though n8n doesn't expose
      custom class hooks. If your n8n version wraps things differently,
      open devtools and nudge the selectors marked ⚠️.
   ========================================================================= */

:root {
	/* =========================================================
	   SCHEMESETU — INDIAN GOVERNMENT / CITIZEN SERVICE THEME
	   (Dark "digital gazette" variant)
	   ========================================================= */

	/* ---- Typography ---- */
	--font-family: 'Inter', 'Open Sans', Arial, sans-serif;
	--font-family-display: 'Tiro Devanagari Hindi', 'Noto Serif', 'Georgia', serif;
	--font-weight-normal: 400;
	--font-weight-bold: 600;
	--font-size-body: 13px;
	--font-size-label: 12px;
	--font-size-test-notice: 12px;
	--font-size-input: 14px;
	--font-size-header: 26px;
	--font-size-paragraph: 14px;
	--font-size-link: 13px;
	--font-size-error: 12px;
	--font-size-html-h1: 30px;
	--font-size-html-h2: 22px;
	--font-size-html-h3: 18px;
	--font-size-html-h4: 15px;
	--font-size-html-h5: 13px;
	--font-size-html-h6: 11px;
	--font-size-subheader: 13px;

	/* =========================================================
	   NATIONAL / GOVERNMENT COLOUR PALETTE
	   ========================================================= */
	--color-saffron: #ff7a1a;
	--color-saffron-deep: #e35f00;
	--color-green: #1c8a3f;
	--color-white: #ffffff;
	--color-government-blue: #2f6fb0;
	--color-deep-blue: #16324f;
	--color-chakra-blue: #3a6ea5;

	/* ---- Page ---- */
	--color-background: #120d0a;
	--color-background-pattern: #1a130e;

	/* ---- Header / Text ---- */
	--color-header: #f7ede1;
	--color-label: #c9b8a4;
	--color-html-text: #e7dccc;
	--color-header-subtext: #9c8a76;

	/* ---- Links ---- */
	--color-link: #ff9a45;
	--color-html-link: #ff9a45;

	/* ---- Cards ---- */
	--color-card-bg: #1c140f;
	--color-card-border: #3a2a1e;
	--color-card-shadow: rgba(0, 0, 0, 0.45);

	/* ---- Inputs ---- */
	--color-input-bg: #241a13;
	--color-input-border: #493525;
	--color-input-text: #f3e9dc;
	--color-focus-border: #ff7a1a;

	/* ---- Submit ---- */
	--color-submit-btn-bg: linear-gradient(135deg, #ff9a45 0%, #e35f00 100%);
	--color-submit-btn-text: #1a1006;

	/* ---- Clear ---- */
	--color-clear-button-bg: #493525;

	/* ---- Validation ---- */
	--color-error: #ff6b6b;
	--color-required: #ff7a1a;

	/* ---- Information / Notice ---- */
	--color-test-notice-text: #f0c98a;
	--color-test-notice-bg: #2a2013;
	--color-test-notice-border: #6b4d1e;

	/* =========================================================
	   BORDER RADII — restrained, official
	   ========================================================= */
	--border-radius-card: 14px;
	--border-radius-input: 8px;
	--border-radius-clear-btn: 50%;
	--card-border-radius: 14px;

	/* =========================================================
	   SPACING
	   ========================================================= */
	--padding-container-top: 36px;
	--padding-card: 30px;
	--card-padding: 30px;
	--padding-test-notice-vertical: 12px;
	--padding-test-notice-horizontal: 18px;
	--margin-bottom-card: 22px;
	--card-margin-bottom: 22px;
	--padding-form-input: 13px;

	/* =========================================================
	   DIMENSIONS
	   ========================================================= */
	--container-width: 540px;
	--submit-btn-height: 52px;
	--checkbox-size: 18px;

	/* =========================================================
	   SHADOW
	   ========================================================= */
	--box-shadow-card:
		0 1px 0 rgba(255, 255, 255, 0.03) inset,
		0 20px 45px rgba(0, 0, 0, 0.5);
	--opacity-placeholder: 0.45;
}

/* =========================================================================
   STRUCTURAL ENHANCEMENTS
   Generic-selector rules that don't depend on n8n's internal class names.
   ========================================================================= */

/* Page backdrop: warm charcoal with a very faint Ashoka-chakra watermark */
body {
	background-color: var(--color-background) !important;
	background-image:
		radial-gradient(circle at 50% -10%, rgba(255, 122, 26, 0.06), transparent 55%),
		repeating-radial-gradient(circle at 50% 50%, rgba(255, 255, 255, 0.015) 0px, rgba(255,255,255,0.015) 1px, transparent 1px, transparent 60px);
}

/* Card: tricolour thread across the top edge, like a letterhead ribbon */
.n8n-form,
.form-container,
main form,
[class*="container"] > form {
	position: relative;
}

.n8n-form::before,
.form-container::before,
[class*="card"]::before {
	content: "";
	display: block;
	height: 4px;
	width: 100%;
	background: linear-gradient(
		90deg,
		var(--color-saffron) 0%,
		var(--color-saffron) 32%,
		var(--color-white) 32%,
		var(--color-white) 68%,
		var(--color-green) 68%,
		var(--color-green) 100%
	);
	border-radius: var(--card-border-radius) var(--card-border-radius) 0 0;
	margin: -1px -1px 0 -1px;
}

/* Form title in the display face, with a small chakra emblem beside it */
.n8n-form h1,
.form-title,
h1 {
	font-family: var(--font-family-display) !important;
	letter-spacing: 0.2px;
	position: relative;
	padding-left: 34px;
}

.n8n-form h1::before,
.form-title::before,
h1::before {
	content: "";
	position: absolute;
	left: 0;
	top: 50%;
	transform: translateY(-50%);
	width: 26px;
	height: 26px;
	border-radius: 50%;
	background: var(--color-chakra-blue);
	background-image:
		repeating-conic-gradient(
			from 0deg,
			#1c140f 0deg 7.5deg,
			var(--color-chakra-blue) 7.5deg 15deg
		);
	box-shadow: 0 0 0 2px var(--color-chakra-blue) inset;
}

/* Section headings ("1. Personal Demographics" etc.) — official red-orange,
   with a hairline rule that reads like a gazette divider */
.form-section-title,
[class*="section-title"],
h2, h3 {
	color: var(--color-saffron) !important;
	text-transform: uppercase;
	font-size: 13px;
	font-weight: var(--font-weight-bold);
	letter-spacing: 0.6px;
	border-bottom: 1px solid var(--color-card-border);
	padding-bottom: 10px;
	margin-top: 6px !important;
}

/* Labels: small caps, muted warm grey, official form-tag feel */
label,
.parameter-label,
[class*="label"] {
	text-transform: uppercase;
	letter-spacing: 0.5px;
	font-weight: var(--font-weight-bold);
	color: var(--color-label) !important;
}

/* Text / number inputs, textareas, selects */
input[type="text"],
input[type="number"],
input[type="email"],
input[type="tel"],
textarea,
select {
	background-color: var(--color-input-bg) !important;
	border: 1px solid var(--color-input-border) !important;
	color: var(--color-input-text) !important;
	border-radius: var(--border-radius-input) !important;
	transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

input:focus,
select:focus,
textarea:focus {
	border-color: var(--color-focus-border) !important;
	box-shadow: 0 0 0 3px rgba(255, 122, 26, 0.18) !important;
	outline: none !important;
}

/* ⚠️ Pill-style choice groups (Gender / Area Type / any radio group).
   n8n renders radio options as a list of label+input pairs — this turns
   each option into a bordered pill and highlights the checked one, the
   same pattern as the reference screenshot. */
.parameter-input-radio-container,
[class*="radio-container"],
[class*="radio-input-container"] {
	display: flex;
	gap: 10px;
}

.parameter-input-radio-container label,
[class*="radio-container"] label,
[class*="radio-input-container"] label {
	flex: 1;
	text-align: center;
	padding: 13px 10px;
	border: 1.5px solid var(--color-input-border);
	border-radius: var(--border-radius-input);
	background-color: var(--color-input-bg);
	color: var(--color-html-text);
	cursor: pointer;
	text-transform: none;
	letter-spacing: 0;
	font-weight: var(--font-weight-normal);
	transition: all 0.15s ease;
}

.parameter-input-radio-container input:checked + label,
[class*="radio-container"] input:checked + label,
[class*="radio-input-container"] input:checked + label {
	border-color: var(--color-saffron) !important;
	color: var(--color-saffron) !important;
	background-color: rgba(255, 122, 26, 0.08) !important;
	font-weight: var(--font-weight-bold);
}

/* Native radio/checkbox dots recoloured to saffron when checked */
input[type="radio"],
input[type="checkbox"] {
	accent-color: var(--color-saffron);
	width: var(--checkbox-size);
	height: var(--checkbox-size);
}

/* Consent / declaration notice strip (matches the "I agree..." row) */
.notice, .test-notice, [class*="notice"] {
	background-color: var(--color-test-notice-bg) !important;
	border: 1px solid var(--color-test-notice-border) !important;
	color: var(--color-test-notice-text) !important;
	border-radius: var(--border-radius-input);
}

/* Submit button — solid saffron gradient, small arrow cue, letterhead weight */
button[type="submit"],
.submit-button,
[class*="submit"] button {
	background: var(--color-submit-btn-bg) !important;
	color: var(--color-submit-btn-text) !important;
	font-weight: 700 !important;
	letter-spacing: 0.3px;
	text-transform: uppercase;
	font-size: 13px;
	border: none !important;
	border-radius: var(--border-radius-input) !important;
	box-shadow: 0 10px 24px rgba(255, 122, 26, 0.28);
	transition: transform 0.12s ease, box-shadow 0.12s ease;
}

button[type="submit"]:hover,
.submit-button:hover,
[class*="submit"] button:hover {
	transform: translateY(-1px);
	box-shadow: 0 14px 30px rgba(255, 122, 26, 0.36);
}

/* Small print / footer trust line under the button, if n8n renders one */
.n8n-powered-by, [class*="powered-by"] {
	color: var(--color-header-subtext) !important;
	opacity: 0.7;
}

