options.customCss:
/* =========================================================================
   SCHEMESETU — Completion Screen — v3
   Paste into: Form Trigger node → On n8n Form Submission →
   Show Completion Screen → Options → Custom Form Styling

   KEY FIX: colour is now set on the CARD CONTAINER ITSELF, not on the
   inner tags. That way, even if n8n's sanitizer strips a tag (like it
   did to your <h3>/<div>), whatever text is left behind still inherits
   light text colour instead of falling back to default black.
   Also forces left alignment everywhere — no more centred wall of text.
   ========================================================================= */

:root {
	--font-family: 'Inter', 'Open Sans', Arial, sans-serif;
	--font-family-display: 'Tiro Devanagari Hindi', 'Noto Serif', 'Georgia', serif;
	--color-saffron: #ff7a1a;
	--color-green: #1c8a3f;
	--color-white: #ffffff;
	--color-chakra-blue: #3a6ea5;
	--color-background: #120d0a;
	--color-header: #f7ede1;
	--color-html-text: #e7dccc;
	--color-header-subtext: #9c8a76;
	--color-html-link: #ff9a45;
	--card-border-radius: 14px;
}

body {
	background-color: var(--color-background) !important;
	background-image: radial-gradient(circle at 50% -10%, rgba(255, 122, 26, 0.06), transparent 55%);
}

[class*="container"],
[class*="card"],
main {
	background-color: var(--color-background) !important;
}

/* The card that wraps the whole completion message.
   color is set HERE so any surviving/unwrapped text inherits it —
   this is the fix for the black scheme-name text. */
[class*="container"] > div,
[class*="card"] {
	background-color: #1c140f !important;
	border: 1px solid #3a2a1e !important;
	border-radius: var(--card-border-radius) !important;
	color: var(--color-html-text) !important;
	position: relative;
}

[class*="container"] > div::before,
[class*="card"]::before {
	content: "";
	display: block;
	height: 4px;
	width: 100%;
	background: linear-gradient(90deg,
		var(--color-saffron) 0%, var(--color-saffron) 32%,
		var(--color-white) 32%, var(--color-white) 68%,
		var(--color-green) 68%, var(--color-green) 100%);
	border-radius: var(--card-border-radius) var(--card-border-radius) 0 0;
	margin: -1px -1px 0 -1px;
}

/* Title, chakra beside it (unchanged from last fix — this part worked) */
h1 {
	font-family: var(--font-family-display) !important;
	color: var(--color-header) !important;
	display: flex !important;
	align-items: center;
	justify-content: center;
	gap: 10px;
	text-align: center;
}
h1::before {
	content: "";
	display: block;
	width: 22px;
	height: 22px;
	flex-shrink: 0;
	border-radius: 50%;
	background-image: repeating-conic-gradient(from 0deg, #1c140f 0deg 7.5deg, var(--color-chakra-blue) 7.5deg 15deg);
	box-shadow: 0 0 0 2px var(--color-chakra-blue) inset;
}

/* Force LEFT alignment on every text-bearing tag — kills the
   centred zig-zag wall of text */
p, li, span, strong, b {
	text-align: left !important;
	color: var(--color-html-text) !important;
}

/* Scheme name — the <strong> tag */
strong {
	display: block;
	color: var(--color-header) !important;
	font-size: 15.5px;
	margin-top: 4px;
}

/* Field labels — the <b> tags ("Why it matches", "Benefit"...) */
b {
	color: var(--color-label, #c9b8a4) !important;
	text-transform: uppercase;
	font-size: 10.5px;
	letter-spacing: 0.4px;
	display: block;
	margin-bottom: 2px;
	margin-top: 8px;
}

/* Divider between schemes — replaces the missing card border */
hr {
	border: none;
	border-top: 1px solid #3a2a1e;
	margin: 18px 0 14px;
}
hr:first-of-type { margin-top: 20px; }

/* Links — including the Apply Now line */
a, a:visited {
	color: var(--color-html-link) !important;
	text-decoration: none;
	font-weight: 700;
	border-bottom: 1px solid rgba(255, 154, 69, 0.4);
}
a:hover { border-bottom-color: var(--color-html-link); }

parameters.jsCode:
// ============================================================================
// n8n CODE NODE — "Formatter" — v4
// FIX: v3 assumed every scheme starts with "1. ", "2. " etc. This run the
// model skipped numbering entirely, so the split found nothing and the
// whole response fell through as one unformatted paragraph.
// v4 no longer depends on numbering at all — it anchors on the field
// labels ("Why it matches:", "Benefit:", "Eligibility:", "Status:",
// "Apply:"), which have stayed consistent across both of your runs.
// ============================================================================

const raw = $input.first().json.candidates[0].content.parts[0].text;

const firstIdx = raw.indexOf('Why it matches:');

// Everything before the first "Why it matches:" is intro text + the
// first scheme's name run together. Split on a blank line to separate
// them; if there's no blank line, treat it all as the name.
let intro = '';
let workingText = raw;

if (firstIdx !== -1) {
	const preBlock = raw.slice(0, firstIdx).trim();
	const parts = preBlock.split(/\n\s*\n/);
	let firstName;
	if (parts.length > 1) {
		intro = parts.slice(0, -1).join(' ').trim();
		firstName = parts[parts.length - 1].trim();
	} else {
		firstName = preBlock;
	}
	workingText = firstName + '\n' + raw.slice(firstIdx);
}

function escapeHtml(str) {
	return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Anchor-based extraction: each match consumes one full scheme entry and
// the next exec() call picks up right where the last one left off, so
// this works whether or not entries are numbered.
const re = /([\s\S]*?)Why it matches:\s*([\s\S]*?)Benefit:\s*([\s\S]*?)Eligibility:\s*([\s\S]*?)Status:\s*([\s\S]*?)Apply:\s*(\S+)/g;

let match;
let i = 0;
let cardsHtml = '';

while ((match = re.exec(workingText)) !== null) {
	i++;
	const name = escapeHtml(match[1].trim().replace(/^\d+\.\s*/, '')); // strip a leading number if present
	const why = escapeHtml(match[2].trim());
	const benefit = escapeHtml(match[3].trim());
	const eligibility = escapeHtml(match[4].trim());
	const status = escapeHtml(match[5].trim());
	const applyUrl = match[6];
	const emoji = /strong/i.test(status) ? '🟢' : '🟡';

	cardsHtml += `
<hr>
<p><strong>${i}. ${name}</strong></p>
<p><b>Why it matches</b> ${why}</p>
<p><b>Benefit</b> ${benefit}</p>
<p><b>Eligibility</b> ${eligibility}</p>
<p>${emoji} ${status}</p>
<p><a href="${applyUrl}" target="_blank" rel="noopener">Apply Now →</a></p>`;
}

// Anything left after the last match (e.g. a closing "Please verify
// eligibility..." note) gets appended as a plain closing line.
const leftover = workingText.slice(re.lastIndex).trim();

// Fallback: if the anchor regex found nothing at all (fields missing or
// completely different format), at least show the raw text instead of
// silently returning blank.
const html = i > 0
	? `<p>${escapeHtml(intro)}</p>\n${cardsHtml}${leftover ? `\n<p><i>${escapeHtml(leftover)}</i></p>` : ''}`
	: `<p>${escapeHtml(raw)}</p>`;

return [{
	json: {
		html: html
	}
}];
